	public void OnSceneLoaded(Scene scene, LoadSceneMode loadSceneMode)
	{
		if (!NextLevelLoader.InTierScene(string.Empty))
		{
			floorIndicatorText.text = string.Empty;
			floorIndicatorText.text = GameController.StageTitle;
			inTierScene = false;
			if (IsActive)
			{
				Disable();
			}
		SetFontSize();
		UpdateStageOrder();
		minimapCamera.enabled = true;
		canvas.enabled = true;
		minimapWasEnabled = GameController.minimap.IsActive();
		GameController.minimap.Disable();
	}

	private void LateUpdate()
	{
		if (IsActive && inTierScene)
		{
			SetPosition(stageOrigin * 0.5f + (stageAvgPos + Camera.main.transform.position) * 0.25f);
		}
	}

	private void Update()
	{
		if (!inTierScene || GameController.minimap == null || LoadingScreen.loading || GameUI.pauseMenu.paused)
		{
			if (IsActive)
			{
				Disable();
			}
			return;
		}
		if (InputController.GetAnyDeviceButtonDown("Map") != null)
		{
			if (IsActive)
			{
				Disable();
			}
			else
			{
				Activate();
			}
		}
		revealPercentageText.text = Minimap.RevealedPercentage;
	}

	private void SetPosition(Vector3 givenPosition)
	{
		givenPosition.z = zPosition;
		transform.position = givenPosition;
	}

	private void UpdateStageOrder()
	{
		for (int i = 0; i < stageIndicators.Length; i++)
		{
			if (i >= GameController.MaxTierCount || i >= GameController.levelNameList.Count)
			{
				stageIndicators[i].enabled = false;
				continue;
			}
			switch (GameController.levelNameList[i])
			{
			case "Ice":
				stageIndicators[i].sprite = iceSprite;
				break;
			case "Earth":
				stageIndicators[i].sprite = earthSprite;
				break;
			case "Fire":
				stageIndicators[i].sprite = fireSprite;
				break;
			case "Air":
				stageIndicators[i].sprite = airSprite;
				break;
			case "Lightning":
				stageIndicators[i].sprite = lightningSprite;
				break;
			}
			stageIndicators[i].enabled = true;
		}
	}

