using Chaos.AnimatorExtensions;
using UnityEngine;

public class Credits : MonoBehaviour
{
	public static bool transitionToTitle = true;

	private Animator anim;

	private bool transitionToNextScene;

	private bool transitionCalled;

	private ChaosQuickStopwatch delayStopwatch = new ChaosQuickStopwatch(2f);

	private void Awake()
	{
		anim = GetComponent<Animator>();
	}

	private void Start()
	{
		GameController.overlayEffects.anim.Play("BlackToTrans", -1, 0f);
		delayStopwatch.IsRunning = true;
	}

	private void Update()
	{
		if (!transitionToNextScene)
		{
			if (anim.AnimPlayed() || SkipRequested())
			{
				transitionToNextScene = true;
				GameController.overlayEffects.anim.Play("FadeToBlack", -1, 0f);
			}
		}
		else if (!transitionCalled && GameController.overlayEffects.anim.AnimPlayed())
		{
			GameController.overlayEffects.anim.Play("Hidden", -1, 0f);
			anim.Play("Hide", -1, 0f);
			if (transitionToTitle)
			{
				GameController.LoadLevel("TitleScreen");
			}
			else
			{
				GameUI.deathSummary.Activate(0f);
			}
			transitionCalled = true;
		}
	}

	private bool SkipRequested()
	{
		if (delayStopwatch.IsRunning)
		{
			return false;
		}
		return InputController.GetAnyDeviceButtonDown("Confirm") != null || InputController.GetAnyDeviceButtonDown("Cancel") != null;
	}
}
using System.Collections;
using System.Collections.Generic;
using Steamworks;
using UnityEngine;
using UnityEngine.SceneManagement;

public class InitialLoad : MonoBehaviour
{
	private Animator anim;

	public static bool useSteamManager = true;

	private void Awake()
	{
		anim = GetComponent<Animator>();
	}

	private void Start()
	{
		ChaosBundle.LoadBundle();
		SoundManager.muteAudio = true;
		if (GameController.resetGameDataQueued)
		{
			GameController.resetGameDataQueued = false;
			GameDataManager.ResetAllData();
			if (Player.NewSpellManager != null)
			{
				Player.NewSpellManager.Reset();
			}
			if (Player.newItems != null)
			{
				foreach (List<string> value in Player.newItems.Values)
				{
					value?.Clear();
				}
			}
		}
		StartCoroutine(LoadTitleScreenAsync());
	}

	private IEnumerator LoadTitleScreenAsync()
	{
		if (useSteamManager)
		{
			yield return StartCoroutine(LoadSteam());
		}
		else
		{
			GameDataManager.LoadInitial(mainInit: true);
		}
		yield return Globals.waitForQuarter;
		Object.Instantiate(ChaosBundle.Get("Assets/Prefabs/MainCamera.prefab"));
		Object.Instantiate(ChaosBundle.Get("Assets/Prefabs/GameController.prefab"));
		if (useSteamManager)
		{
			AchievementManager.Initialize(GameController.Instance);
		}
		yield return Globals.waitForQuarter;
		AsyncOperation asyncOp = SceneManager.LoadSceneAsync("TitleScreen", LoadSceneMode.Additive);
		yield return asyncOp;
		while (!asyncOp.isDone)
		{
			yield return null;
		}
		SoundManager.muteAudio = false;
		anim.Play("FadeOut", -1, 0f);
		SoundManager.PlayBGM("TitleScreen");
		if (Input.GetKey(KeyCode.Escape))
		{
			GameDataManager.gameSettings.Reset();
		}
	}

	private IEnumerator LoadSteam()
	{
		Object.Instantiate(ChaosBundle.Get("Assets/Prefabs/SteamManager.prefab"));
		while (!SteamManager.Initialized)
		{
			yield return null;
		}
		GameDataManager.steamIDStr = SteamUser.GetSteamID().GetAccountID().m_AccountID + "/";
		GameDataManager.LoadInitial(mainInit: true);
	}
}
using Chaos.AnimatorExtensions;
using UnityEngine;
using UnityEngine.UI;

public class LoadingScreen : MonoBehaviour
{
	public delegate void LoadCompleteEvent();

	private static LoadingScreen instance;

	private GameObject bgOverlay;

	private Text progressText;

	private Text promptText;

	private Canvas canvas;

	private Animator anim;

	private Text loopCounterText;

	public LoadCompleteEvent loadCompleteEventHandlers;

	public GameProgressBoard gameProgressBoard;

	private bool fadeOutQueued;

	private bool promptFadeIn;

	private bool useFlickering;

	private float fadeTime = 0.5f;

	private int fadeStopwatchID = -1;

	private bool mouseWasVisible;

	[HideInInspector]
	public bool queueDisableOnly;

	private bool waitingForTPAnim;

	private bool tpFrameSkipped;

	private AnimEffect tpEffect;

	private string prevLevelName;

	private int prevStageCount;

	private int prevTierCount;

	private string levelName;

	public static bool loading;

	public static LoadingScreen Instance => instance;

	private void Awake()
	{
		if (instance != null && instance != this)
		{
			Object.Destroy(gameObject);
			return;
		}
		instance = this;
		bgOverlay = transform.Find("BlackOverlay").gameObject;
		progressText = transform.Find("BlackOverlay/Progress").GetComponent<Text>();
		promptText = transform.Find("BlackOverlay/Prompt").GetComponent<Text>();
		canvas = GetComponent<Canvas>();
		anim = GetComponent<Animator>();
		gameProgressBoard = transform.Find("GameProgress").GetComponent<GameProgressBoard>();
		loopCounterText = transform.Find("GameProgress/StartCircle/LoopCounter/Text").GetComponent<Text>();
		TextManager.AddUIRef(string.Empty, progressText);
		TextManager.AddUIRef(string.Empty, promptText);
		TextManager.AddUIRef(string.Empty, loopCounterText);
		Object.DontDestroyOnLoad(gameObject);
	}

	private void Start()
	{
		Disable();
	}

	private void Update()
	{
		if (loading && GameUI.pauseMenu.paused)
		{
			GameUI.TogglePause();
		}
		if (fadeOutQueued && gameProgressBoard.pieceFinishedMoving)
		{
			fadeOutQueued = false;
			FadeOut();
			return;
		}
		if (useFlickering && ChaosStopwatch.Check(fadeStopwatchID))
		{
			fadeStopwatchID = ChaosStopwatch.Begin(fadeTime);
			promptText.CrossFadeAlpha((!promptFadeIn) ? 0.6f : 1f, 0.25f, ignoreTimeScale: true);
			promptFadeIn = !promptFadeIn;
		}
		if (!waitingForTPAnim)
		{
			return;
		}
		if (!tpFrameSkipped)
		{
			tpFrameSkipped = true;
		}
		else if ((tpEffect == null || tpEffect.anim.AnimPlayed(0.25f) || !tpEffect.playing) && GameController.activePlayers.Length > 0)
		{
			AnnounceStage();
			waitingForTPAnim = false;
			StopLoading();
			tpFrameSkipped = false;
			tpEffect = null;
			GameController.PauseAllPlayers(state: false);
			Player[] activePlayers = GameController.activePlayers;
			foreach (Player player in activePlayers)
			{
				player.Show();
			}
		}
	}

	public void SetProgressText(string txt)
	{
		progressText.text = txt;
	}

	public void SetPromptText(string txt)
	{
		promptText.text = txt;
	}

	public void Enable(bool gameProgressMode = false)
	{
		canvas.enabled = true;

		canvas.enabled = true;
		waitingForTPAnim = false;
		tpFrameSkipped = false;
		bgOverlay.SetActive(value: true);
		anim.Play("Enabled", -1, 0f);
		if (gameProgressMode)
		{
			gameProgressBoard.Enable();
		}
		if (!GameController.mouseCursor.Hidden)
		{
			mouseWasVisible = true;
			GameController.mouseCursor.Hide();
		}
		else
		{
			mouseWasVisible = false;
		}
		prevLevelName = Application.loadedLevelName;
		prevStageCount = GameController.stageCount;
		prevTierCount = GameController.tierCount;
		loopCounterText.enabled = true;
		loopCounterText.text = ((GameController.loopCount <= 0) ? string.Empty : ("x" + (GameController.loopCount + 1)));
		loading = true;
	}

	public void StopLoading()
	{
		loading = false;
		if ((prevLevelName != levelName || prevStageCount != GameController.stageCount || prevTierCount != GameController.tierCount) && loadCompleteEventHandlers != null)
		{
			loadCompleteEventHandlers();
		}
	}

	public void FadeOut()
	{
		if (gameProgressBoard.visible && !gameProgressBoard.pieceFinishedMoving)
		{
			fadeOutQueued = true;
			return;
		}
		anim.Play("FadeOut", -1, 0f);
		gameProgressBoard.Disable();
		SetProgressText(string.Empty);
		loopCounterText.enabled = false;
		if (mouseWasVisible)
		{
			GameController.mouseCursor.Show();
			mouseWasVisible = false;
		}
	}

	public void Disable()
	{
		canvas.enabled = false;
		bgOverlay.SetActive(value: false);
		if (queueDisableOnly)
		{
			queueDisableOnly = false;
			StopLoading();
			return;
		}
		levelName = Application.loadedLevelName;
		if (levelName == "Credits" || levelName == "PlayerRoomTutorial")
		{
			StopLoading();
			return;
		}
		if (levelName == "PvPArena")
		{
			StopLoading();
			GameController.PauseAllPlayers(state: false);
			Player[] activePlayers = GameController.activePlayers;
			foreach (Player player in activePlayers)
			{
				player.Show();
			}
			return;
		}
		int num = -1;
		Player[] activePlayers2 = GameController.activePlayers;
		foreach (Player player2 in activePlayers2)
		{
			if (num == -1)
			{
				num = player2.playerID;
				tpEffect = PoolManager.GetPoolItem<AnimEffect>("TeleportEffect");
				tpEffect.Play(player2.transform.position, string.Empty);
			}
			else
			{
				player2.TeleportToPartner(num, showSpawnPortal: false, excludeOrigin: true);
			}
			waitingForTPAnim = true;
		}
		if (Application.loadedLevelName == "Tutorial" && GameController.activePlayers.Length == 0)
		{
			StopLoading();
			waitingForTPAnim = true;
		}
		if (!waitingForTPAnim)
		{
			StopLoading();
			AnnounceStage();
		}
	}

	private void AnnounceStage()
	{
		if (NextLevelLoader.InTierScene(string.Empty))
		{
			GameController.stageTitleUI.Announce(GameController.StageTitle, 0f, 60, null, null, showUnderline: true, 1f, 0f, numberMode: false, null, null, null, 0.2f);
			return;
		}
		levelName = Application.loadedLevelName;
		if (levelName == "Hub" || levelName == "Tutorial")
		{
			GameController.stageTitleUI.Announce(TextManager.GetUIText("stageTitle-" + levelName));
		}
	}
}
12:   Порог тревоги: доля HP ≤ 0.3 и > 0 — фон и портрет красятся одним цветом и мигают белый↔красный; значение лерпа 0↔1 растёт со скоростью max(0.3 − доля, 0.1) × 22 за секунду (2.2 при доле ≥ 0.2, до 6.6 у нуля), т.е. параметр — **полуциклы**, полный цикл белый→красный→белый = 2 / скорость. Звук тревоги один раз при входе в зону (сброс при выходе), на экране загрузки не играет. Текст HP — усечение до целого, «текущее/максимум (с модификаторами)».
22:   - **Параметры объявлений:** название этапа — показ через 0.2 с после загрузки, шрифт 60, удержание 0, с подчёркиванием. «Бой»: шрифт 180, красный, скорость анимации 1.75, толстая линия (масштаб Y 5). «Победа»: шрифт 120, цвет (0.93, 0.85, 0.4), кайма (0.6, 0.41, 0.2), анимация со старта 0.5, удержание 1 с, конфетти: 24 в центре + по 8 слева и справа со сдвигом ±2.5 м. «Комбо»: «N» + текст, красный, шрифт 60, 0.75 с.
25:12. **Полоски врагов.** Два вида. (а) **Мини-полоска над головой** (только при реликвии «полоски», пул 25): цвет (0.6, 0, 0, 0.8), размер 0.44–0.56 × 0.45–0.46 внутри рамки; показывается для обычных врагов, вошедших в зону-активатор (не для мини-боссов, боссов и тренировочной куклы); активатор включается только на этажах и заново — через кадр после загрузки сцены. (б) **Полоска босса/мини-босса**: имя, заливка, след (п.1, 0.4 с), щит; появляется всегда; прозрачность 0.01 → 1 за 0.25 с и «налив» заливки 0 → полная за 1 с.
30:   - **Детали:** подтверждение в меню паузы принимается кнопкой «Подтверждение» **или** клавишей пробел (зашито). Меню открывается по **нажатию** «Меню» и закрывается по **отпусканию** «Меню» или «Отмена». Пауза запрещена: при всех мёртвых, при активном итоге этажа, на экране загрузки (отложенная пауза выставляется после загрузки), в сцене титров; клавиша «Меню» не открывает паузу у клавиатурного игрока в состоянии «Paused» (меню снаряжения/хаб-окно открыто). Отключение устройства основного контроллера ставит паузу в очередь, если меню паузы не открыто. Экран загрузки принудительно закрывает меню паузы. Размытие — включение компонента на камере.
42:16б. **Уведомление о разблокировке:** отдельная очередь (ёмкость 20 — не предел), 4 типа: аркана, фирменная, реликвия, облик (палитра облика); заголовок = имя + «разблокировано», подзаголовок по типу. Показ: анимация «появление», удержание 1.5 с после 75 % проигрывания, затем «скрытие». Звук «вступление» — только если очередь пуста и ничего не показывается; звук «выход» — при каждом показе. Очередь и анимация сбрасываются при загрузке уровня.
49:   - **Управление:** вверх/вниз с заворотом 0..5, задержка первого повтора 0.4 с, дальше автоповтор 0.2 с; «Подтверждение» → запрос загрузки, «Взаимодействие» → запрос сохранения (в окне подтверждения по умолчанию «нет»; сохранение в PvP запрещено, звук ошибки). Закрывается по «Отмена» или при удалении игрока дальше 4 м; нижний HUD игрока скрыт, пока окно открыто.
50:   - **Загрузка:** если облик занят другим игроком — остаётся текущий; снаряжается облик; профиль сохраняется; инвентарь очищается (проклятые остаются); стартовая реликвия выдаётся (не в PvP); 6 слотов арканов очищаются и 4 аркана ставятся на **те же индексы**, где были базовая/рывок/обычная/фирменная; фирменной ставится флаг; HP до полного.
65:22. **Полноэкранная карта:** кнопка «карта» переключает (на паузе и экране загрузки закрыта — принудительно закрывается; **вне сцен этажей ничего не происходит**: обработчик завершается раньше чтения кнопки, звука ошибки нет). Центр = 0.5 × начало + 0.25 × (средняя позиция сетки + позиция камеры). Показывает порядок этапов (до 5 иконок стихий — по числу этапов забега), название этапа, %. Открытие прячет компас и миникарту (запоминает, была ли миникарта включена); закрытие возвращает миникарту, только если она была включена и сцена — этаж.

