	public void SelectMenuIndex(int newIndex)
	{
		SelectMenuIndex(newIndex, false);
	}

	public void SelectMenuIndex(int newIndex, bool dirInput = false)
	{
		if ((GameController.mouseCursor.Hidden && !dirInput) || currentState != TitleScreenState.Menu)
		{
			return;
		}
		currentMenuIndex = newIndex;
		if (currentMenuIndex >= menuTextOpts.Length)
		{
			currentMenuIndex = 0;
		}
		else if (currentMenuIndex < 0)
		{
			currentMenuIndex = menuTextOpts.Length - 1;
		}
		for (int i = 0; i < menuTextOpts.Length; i++)
		{
			if (currentMenuIndex == i)
			{
				if (currentMenuIndex == multiplayerOptIndex && !AllowMultiplayer())
				{
					ToggleMenuOption(menuTextOpts[i], enable: true, disableSelected: true);
				}
				else if (currentMenuIndex == versusOptIndex && !AllowMultiplayer())
				{
					ToggleMenuOption(menuTextOpts[i], enable: true, disableSelected: true);
				}
				else
				{
					ToggleMenuOption(menuTextOpts[i]);
				}
			}
			else
			{
				ToggleMenuOption(menuTextOpts[i], enable: false);
			}
		}
		if (startCompleted)
		{
			SoundManager.PlayAudio("MenuMove");
		}
	}

	public void SetectBGIndex(int givenIndex)
	{
		currentBGIndex = (givenIndex + bgCount) % bgCount;
		GameDataManager.gameVars.SetValue(GameVarsKey.TitleBG, currentBGIndex);
		bgImageIndexZero = !bgImageIndexZero;
		bgImages[(!bgImageIndexZero) ? 1u : 0u].sprite = IconManager.GetBGSprite(currentBGIndex);
		if (bgImageIndexZero)
		{
			bgImages[0].CrossFadeAlpha(1f, 0.5f, ignoreTimeScale: false);
			bgImages[1].CrossFadeAlpha(0f, 0.5f, ignoreTimeScale: false);
		}
		else
		{
			bgImages[0].CrossFadeAlpha(0f, 0.5f, ignoreTimeScale: false);
			bgImages[1].CrossFadeAlpha(1f, 0.5f, ignoreTimeScale: false);
		}
	}

	public void ToggleMenuOption(Text menuOpt, bool enable = true, bool disableSelected = false)
	{
		if (enable)
		{
			menuOpt.color = Globals.uiSelectedColor;
			menuOpt.fontSize = TextManager.GetAdjustedFontSize(enabledFontSize);
			if (disableSelected)
			{
				menuOpt.color = Globals.uiNotSelectedColor;
			}
		}
		else
		{
			menuOpt.color = Globals.uiNotSelectedColor;
			menuOpt.fontSize = TextManager.GetAdjustedFontSize(disabledFontSize);
		}
	}

	public bool AllowMultiplayer()
	{
		return ReInput.controllers.controllerCount > 1;
	}

	public void ConfirmMenuOption()
	{
		if (currentState != TitleScreenState.Menu)
		{
			return;
		}
		switch (currentMenuIndex)
		{
		case 0:
			SoundManager.PlayConfirmAudio();
			StartGame();
			break;
		case 1:
			if (!AllowMultiplayer())
			{
				SoundManager.PlayAudio("MenuError");
				GlobalDialog.Display("titleScreen-connect2ndController");
			}
			else
			{
				SoundManager.PlayConfirmAudio();
				StartGame();
				GameController.coopOn = true;
			}
			break;
		case 2:
			if (!AllowMultiplayer())
			{
				SoundManager.PlayAudio("MenuError");
				GlobalDialog.Display("titleScreen-connect2ndController");
			}
			else
			{
				SoundManager.PlayConfirmAudio();
				StartGame(loadPvP: true);
				GameController.coopOn = true;
			}
			break;
		case 3:
			currentState = TitleScreenState.Options;
			GameController.optionsMenu.gameObject.SetActive(value: true);
			GameController.optionsMenu.releaseControlToParent = false;
			Hide();
			SoundManager.PlayConfirmAudio();
			break;
		case 4:
			Credits.transitionToTitle = true;
			GameController.LoadLevel("Credits");
			SoundManager.PlayConfirmAudio();
			break;
		case 5:
			SoundManager.PlayConfirmAudio();
			GameController.Quit();
			break;
		}
	}

