	private void Update()
	{
		HandleMenuStates();
		if (currentMenuIndex == multiplayerOptIndex || currentMenuIndex == versusOptIndex)
		{
			if (!AllowMultiplayer() && menuTextOpts[currentMenuIndex].color != Globals.uiNotSelectedColor)
			{
				ToggleMenuOption(menuTextOpts[currentMenuIndex], enable: true, disableSelected: true);
			}
			else if (AllowMultiplayer() && menuTextOpts[currentMenuIndex].color != Globals.uiSelectedColor)
			{
				ToggleMenuOption(menuTextOpts[currentMenuIndex]);
			}
		}
	}

	public void HandleMenuStates()
	{
		bool flag = false;
		switch (currentState)
		{
		case TitleScreenState.Menu:
			HandleNavigation();
			break;
		case TitleScreenState.Standby:
			HandleBGChange();
			if (InputController.GetAnyDeviceButtonDown("Confirm") != null || InputController.GetAnyDeviceButtonDown("Skill0") != null || InputController.GetAnyDeviceButtonDown("Skill1") != null || InputController.GetAnyDeviceButtonDown("Skill2") != null || InputController.GetAnyDeviceButtonDown("Skill3") != null || InputController.GetAnyDeviceButtonDown("Skill4") != null || InputController.GetAnyDeviceButtonDown("Skill5") != null || InputController.GetAnyDeviceButtonDown("Cancel") != null || InputController.GetAnyDeviceButtonDown("Interact") != null || InputController.GetAnyDeviceButtonDown("Menu") != null)
			{
				anim.Play("Menu", -1, 0f);
				SoundManager.PlayConfirmAudio();
				currentState = TitleScreenState.Menu;
				GameDataManager.SaveGameVars();
				FadeLogoAndExtra(fadeOut: false);
			}
			break;
		case TitleScreenState.Options:
			if (GameController.optionsMenu.releaseControlToParent)
			{
				GameController.optionsMenu.gameObject.SetActive(value: false);
				Show();
				SoundManager.BGMPaused = false;
				flag = true;
				if (GameController.resetGameDataQueued)
				{
					GameController.LoadLevel("InitialLoad");
				}
			}
			break;
		}
		if (flag)
		{
			currentState = TitleScreenState.Menu;
		}
	}

	public void HandleNavigation()
	{
		if (InputController.GetAnyDeviceDirection(InputDirection.Down))
		{
			currentMenuIndex++;
			SelectMenuIndex(currentMenuIndex, dirInput: true);
		}
		else if (InputController.GetAnyDeviceDirection(InputDirection.Up))
		{
			currentMenuIndex--;
			SelectMenuIndex(currentMenuIndex, dirInput: true);
		}
		if (InputController.GetAnyDeviceButtonDown("Confirm") != null)
		{
			ConfirmMenuOption();
		}
		else if (InputController.GetAnyDeviceButtonDown("Cancel") != null)
		{
			anim.Play("CancelMenu", -1, 0f);
			currentState = TitleScreenState.Standby;
		}
	}

	public void HandleBGChange()
	{
		if (!bgStopwatch.IsRunning)
		{
			if (InputController.GetAnyDeviceDirection(InputDirection.Left))
		yield return new WaitForSeconds(1f);
		epilogueWorkerNpc.myDialogID = "MuseumWorkerEpilogue-Landing0";
		epilogueWorkerNpc.ForcePlayerActivation(activePlayer);
		yield return null;
		while (DialogManager.dialogInProgress)
		{
			yield return null;
		}
		Animator playerAnim = null;
		Player[] activePlayers2 = GameController.activePlayers;
		foreach (Player player2 in activePlayers2)
		{
			player2.anim.Play("GetUp", -1, 0f);
			playerAnim = player2.anim;
		}
		yield return null;
		while (playerAnim != null && !playerAnim.AnimPlayed())
		{
			yield return null;
		}
		yield return new WaitForSeconds(0.33f);
		epilogueWorkerNpc.myDialogID = "MuseumWorkerEpilogue-Landing1";
		epilogueWorkerNpc.enabled = true;
		epilogueWorkerNpc.ForcePlayerActivation(activePlayer);
		SoundManager.PlayEpilogueBGM();
		yield return null;
		while (DialogManager.dialogInProgress)
		{
			yield return null;
		}
		GameController.PauseAllPlayers(state: false);
		wakeUpEventDone = true;
	}

	private void SetRunTimeClock()
