	private void LoadPlayerMuseumSpells()
	{
		Player[] activePlayers = GameController.activePlayers;
		foreach (Player player in activePlayers)
		{
			if (!(player == null))
			{
				player.AssignSkillSlot(0, Player.WindSlashBasic.staticID);
				player.AssignSkillSlot(1, Player.DashState.staticID);
				player.AssignSkillSlot(2, Player.ShootFireArc.staticID);
				player.AssignSkillSlot(3, Player.ShootFireball.staticID, setSignature: true, signatureStatus: true);
				player.lowerHUD.cooldownUI.RefreshEntries();
			}
		}
	}

