		otherStatuesTrans.gameObject.SetActive(value: false);
		tempSR = otherOutfitSpriteTrans.GetComponent<SpriteRenderer>();
		if (tempSR != null && Outfit.OutfitDict.ContainsKey(givenData.startOutfit))
		{
			tempSR.material = new Material(tempSR.material);
			tempSR.material.SetFloat("_PaletteIndex", Outfit.OutfitDict[givenData.startOutfit].outfitColorIndex);
			if (givenData.outFitEnhanced)
			{
				Globals.ChaosInst<Transform>(TailorNpc.SparklePrefab, tempSR.transform, tempSR.transform.position + Vector3.up * 1.25f);
			}
		}
		LoadSprite(otherSignatureSpriteTrans, givenData.startSpellSignature, isItem: false);
		LoadSprite(otherRelicSpriteTrans, givenData.startItem);
	}

