private IEnumerator MovePlayerPiece(int stageIndex)
{
	ChaosQuickStopwatch delayStopWatch = new ChaosQuickStopwatch(0.25f)
	{
		IsRunning = true
	};
	while (delayStopWatch.IsRunning)
	{
		yield return null;
	}
	if (stageIndex != 0 || GameController.loopCount == 0)
	{
		p1PieceAnim.Play("Bounce", -1, Random.value);
		if (GameController.coopOn)
		{
			p2PieceAnim.Play("Bounce", -1, Random.value);
		}
	}
	bool p1PieceLanded = false;
	ChaosQuickStopwatch pieceStopWatch = new ChaosQuickStopwatch(1.5f)
	{
		IsRunning = true
	};
	while (pieceStopWatch.IsRunning)
	{
		if (GameController.coopOn)
		{
			p2Piece.position = Vector2.Lerp(startPos + coopPieceOffset[1], endPos + coopPieceOffset[1], pieceStopWatch.TimePercentage);
			if (!p1PieceLanded)
			{
				if (pieceStopWatch.TimePercentage + 0.33f >= 1f)
				{
					p1PieceAnim.Play("Land", -1, 0f);
					p1PieceLanded = true;
				}
				else
				{
					p1Piece.position = Vector2.Lerp(startPos + coopPieceOffset[0], endPos + coopPieceOffset[0], pieceStopWatch.TimePercentage + 0.33f);
				}
			}
		}
		else
		{
			p1Piece.position = Vector2.Lerp(startPos, endPos, pieceStopWatch.TimePercentage);
		}
		dimmersInOrder[stageIndex].color = Color.Lerp(defaultColor, disabledColor, pieceStopWatch.TimePercentage);
		yield return null;
	}
	if (GameController.coopOn)
	{
		p1Piece.position = endPos + coopPieceOffset[0];
		p2Piece.position = endPos + coopPieceOffset[1];
		p2PieceAnim.Play("Land", -1, 0f);
	}
	else
	{
		p1PieceAnim.Play("Land", -1, 0f);
		p1Piece.position = endPos;
	}
	dimmersInOrder[stageIndex].color = disabledColor;
	yield return new WaitForSeconds(0.25f);
	pieceFinishedMoving = true;
}

private void SetModeVars()
{
	if (Level.isBossRushMode)
	{
		curMaxStagesPerTier = 2;
		curStagePositions = bossRushStagePositions;
	}
	else
	{
		curMaxStagesPerTier = 3;
		curStagePositions = stagePositions;
	}
	curMaxTierCount = GameController.MaxTierCount;
}

public void InitializeTierOrders()
{
	if (!initializationReady)
	{
		return;
	}
	SetModeVars();
	HideRegularStages();
	curTotalStageCount = curMaxTierCount * curMaxStagesPerTier + 2;
	curFinalStageIndex = curTotalStageCount - 1;
	stagesInOrder[curFinalStageIndex] = finalBossCircle;
	dimmersInOrder[curFinalStageIndex] = finalBossDimmer;
	string text = null;
	int num = 0;
	for (int i = 1; i < curTotalStageCount - 1; i += curMaxStagesPerTier)
	{
		num = (i - 1) / curMaxStagesPerTier;
		text = NextLevelLoader.GetCurrentTierScene(num);
		switch (text)
		{
		case "Ice":
			if (visible)
			{
				iceBossCircle.gameObject.SetActive(value: true);
			}
			iceBossCircle.anchoredPosition = curStagePositions[num];
			break;
		case "Earth":
			if (visible)
			{
				earthBossCircle.gameObject.SetActive(value: true);
			}
			earthBossCircle.anchoredPosition = curStagePositions[num];
			else
			{
				levelDimmers[text][num2].gameObject.SetActive(value: false);
				levelMarkers[text][num2].gameObject.SetActive(value: false);
			}
			num2--;
			num3--;
		}
		dimmersInOrder[i + curMaxStagesPerTier - 1] = bossDimmers[text];
		stagesInOrder[i + curMaxStagesPerTier - 1] = bossCircles[text];
		bossesInOrder[num] = bossCircles[text];
	}
}

public void ToggleFade(bool fadeIn = true, float duration = 0.25f)
{
	Graphic[] array = graphicComps;
	foreach (Graphic graphic in array)
	{
		graphic.CrossFadeAlpha((!fadeIn) ? 0f : 1f, duration, ignoreTimeScale: false);
	}
}

